<div x-show="statusModal" x-cloak class="fixed inset-0 z-50 flex items-end justify-center bg-black/50 p-3 sm:items-center"><form method="POST" action="{{ route('admin.suggestions.status',$suggestion) }}" @submit="submitting=true" class="w-full max-w-lg rounded-2xl bg-white p-5">@csrf @method('PATCH')<input type="hidden" name="status" :value="nextStatus"><div class="flex justify-between"><h2 class="text-lg font-black">Konfirmasi Perubahan Status</h2><button type="button" @click="statusModal=false"><i class="ri-close-line text-2xl"></i></button></div><p class="mt-2 text-sm text-slate-500">Tujuan: <b x-text="{{ Js::from($labels) }}[nextStatus] || nextStatus"></b></p>@foreach([['rejected','rejection_reason','Alasan penolakan'],['closed','closure_reason','Alasan penutupan'],['implemented','implementation_note','Catatan implementasi']] as [$status,$name,$label])<label x-show="nextStatus==='{{ $status }}'" class="mt-4 block"><span class="text-sm font-bold">{{ $label }} *</span><textarea name="{{ $name }}" :required="nextStatus==='{{ $status }}'" rows="4" class="mt-1 w-full rounded-xl border-slate-300"></textarea></label>@endforeach<p x-show="['rejected','closed','implemented'].includes(nextStatus)" class="mt-3 text-xs font-semibold text-red-600">Status ini terminal pada workflow normal.</p><div class="mt-5 flex gap-2"><button type="button" @click="statusModal=false" class="flex-1 rounded-xl border py-3 font-bold">Batal</button><button :disabled="submitting" class="flex-1 rounded-xl bg-[#318f8c] py-3 font-bold text-white disabled:opacity-50" x-text="submitting?'Memproses...':'Konfirmasi'"></button></div></form></div>
<div x-show="correctionModal" x-cloak class="fixed inset-0 z-50 flex items-end justify-center bg-black/50 p-3 sm:items-center"><form method="POST" action="{{ route('admin.suggestions.correction',$suggestion) }}" @submit="submitting=true" class="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-2xl bg-white p-5">@csrf @method('PATCH')<div class="flex justify-between"><h2 class="text-lg font-black">Koreksi Administratif</h2><button type="button" @click="correctionModal=false"><i class="ri-close-line text-2xl"></i></button></div><p class="mt-2 text-xs text-amber-700">Khusus memperbaiki kesalahan status. Timestamp sesudah status tujuan akan dinormalkan.</p><label class="mt-4 block"><span class="text-sm font-bold">Status yang benar *</span><select name="status" x-model="nextStatus" required class="mt-1 w-full rounded-xl border-slate-300"><option value="">Pilih status</option>@foreach($labels as $value=>$label)@if($value!==$suggestion->status)<option value="{{ $value }}">{{ $label }}</option>@endif @endforeach</select></label><label class="mt-3 block"><span class="text-sm font-bold">Alasan koreksi *</span><textarea name="correction_reason" required minlength="10" rows="3" class="mt-1 w-full rounded-xl border-slate-300"></textarea></label>@foreach([['rejected','rejection_reason','Alasan penolakan'],['closed','closure_reason','Alasan penutupan'],['implemented','implementation_note','Catatan implementasi']] as [$status,$name,$label])<label x-show="nextStatus==='{{ $status }}'" class="mt-3 block"><span class="text-sm font-bold">{{ $label }} *</span><textarea name="{{ $name }}" :required="nextStatus==='{{ $status }}'" rows="3" class="mt-1 w-full rounded-xl border-slate-300"></textarea></label>@endforeach<div class="mt-5 flex gap-2"><button type="button" @click="correctionModal=false" class="flex-1 rounded-xl border py-3 font-bold">Batal</button><button :disabled="submitting" class="flex-1 rounded-xl bg-amber-500 py-3 font-bold text-white">Simpan Koreksi</button></div></form></div>
